<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Animated Solar System</title>
<style>
  body,html{margin:0;overflow:hidden;background:#000;}
  canvas{display:block;}
</style>
</head>
<body>
<canvas id="space"></canvas>
<script>
(() => {
  const canvas = document.getElementById('space');
  const ctx = canvas.getContext('2d');

  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    cx = canvas.width/2;
    cy = canvas.height/2;
  };
  window.addEventListener('resize', resize);
  resize();

  const cx = canvas.width/2, cy = canvas.height/2;

  // Starfield
  const stars = [];
  const STAR_COUNT = 200;
  for (let i=0;i<STAR_COUNT;i++){
    stars.push({
      x: Math.random()*canvas.width,
      y: Math.random()*canvas.height,
      r: Math.random()*1.2+0.2
    });
  }

  // Planet definitions
  const planets = [
    {name:'Mercury',   color:'#aaa',  radius: 58,  size:4, speed:0.047},
    {name:'Venus',     color:'#c90',  radius:108,  size:7, speed:0.035},
    {name:'Earth',     color:'#06f',  radius:150,  size:8, speed:0.030},
    {name:'Mars',      color:'#d44',  radius:228,  size:6, speed:0.024},
    {name:'Jupiter',   color:'#d9a',  radius:778,  size:14,speed:0.013},
    {name:'Saturn',    color:'#fa0',  radius:1429, size:12,speed:0.009},
    {name:'Uranus',    color:'#7ff',  radius:2871, size:10,speed:0.006},
    {name:'Neptune',   color:'#44f',  radius:4495, size:10,speed:0.005}
  ];

  // Scale orbital radii to fit canvas
  const maxOrbit = Math.min(canvas.width, canvas.height)/2 - 20;
  const scale = maxOrbit / Math.max(...planets.map(p=>p.radius));

  let t = 0;
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);

    // draw stars
    ctx.fillStyle = '#fff';
    stars.forEach(s=>{ ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,2*Math.PI); ctx.fill(); });

    // draw Sun
    ctx.fillStyle = '#ffb300';
    ctx.beginPath();
    ctx.arc(cx,cy,20,0,2*Math.PI);
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Sun', cx, cy-30);

    // draw planets
    planets.forEach(p=>{
      const ang = t * p.speed;
      const x = cx + Math.cos(ang) * p.radius * scale;
      const y = cy + Math.sin(ang) * p.radius * scale;

      // orbit path
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.beginPath();
      ctx.arc(cx,cy,p.radius*scale,0,2*Math.PI);
      ctx.stroke();

      // planet
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(x,y,p.size,0,2*Math.PI);
      ctx.fill();

      // label
      ctx.fillStyle = '#fff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(p.name, x, y - p.size - 4);
    });

    t+=1;
    requestAnimationFrame(draw);
  }
  draw();
})();
</script>
</body>
</html>
```

The script creates a starfield background, draws the Sun at the canvas centre, and animates eight planets on scaled circular orbits with different speeds, labeling each as they move.
